      description: 'Comparing the best open world games',
      videoUrl: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4',
      thumbnail: 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&h=400&fit=crop',
      duration: '24:50',
      category: 'reviews',
      views: '8.7M',
      uploadDate: '1 week ago'
    }
  ];

  const filteredVideos = selectedCategory === 'all' 
    ? videos 
    : videos.filter(video => video.category === selectedCategory);

  const handleVideoSelect = (video: VideoItem) => {
    if (onVideoClick) {
      onVideoClick();
    } else {
      setSelectedVideo(video);
      setIsPlaying(true);
    }
  };

  const handleCloseVideo = () => {
    setSelectedVideo(null);
    setIsPlaying(false);
    if (videoRef.current) {
      videoRef.current.pause();
    }
  };

  const handleVideoHover = (videoId: number) => {
    setHoveredVideo(videoId);
    const video = videoRefs.current[videoId];
    if (video) {
      video.currentTime = 0;
      video.play().catch((err) => {
        console.log('Video play failed:', err);
      });
    }
  };

  const handleVideoLeave = (videoId: number) => {
    setHoveredVideo(null);
    const video = videoRefs.current[videoId];
    if (video) {
      video.pause();
      video.currentTime = 0;
    }
  };

  const setVideoRef = (videoId: number) => (el: HTMLVideoElement | null) => {
    videoRefs.current[videoId] = el;
  };

  const formatDuration = (duration: string) => {
    return duration;
  };

  return (
    <div className="videos-page">
      <div className="videos-container">
        {/* Header */}
        <div className="videos-header">
          <h1 className="videos-main-title">Game Videos</h1>
          <p className="videos-subtitle">Watch the latest gameplay, reviews, and exclusive content</p>
        </div>

        {/* Category Filter */}
        <div className="category-filter">
          {videoCategories.map((category) => (
            <button
              key={category.id}
              className={`category-btn ${selectedCategory === category.id ? 'active' : ''}`}
              onClick={() => setSelectedCategory(category.id)}
            >
              <span className="category-icon">{category.icon}</span>
              <span className="category-name">{category.name}</span>
            </button>
          ))}
        </div>

        {/* Videos Grid */}
        <div className="videos-grid">
          {filteredVideos.map((video) => (
            <div 
              key={video.id} 
              className="video-card" 
              onClick={() => handleVideoSelect(video)}
              onMouseEnter={() => handleVideoHover(video.id)}
              onMouseLeave={() => handleVideoLeave(video.id)}
            >
              <div className="video-thumbnail-container">
                <video
                  ref={setVideoRef(video.id)}
                  src={video.videoUrl}
                  muted
                  playsInline
                  loop
                  preload="metadata"
                  className={`video-element ${hoveredVideo === video.id ? 'playing' : ''}`}
                  style={{ backgroundImage: `url(${video.thumbnail})` }}
                />
                <img src={video.thumbnail} alt={video.title} className={`video-thumbnail ${hoveredVideo === video.id ? 'hidden' : ''}`} />
                <div className={`video-overlay ${hoveredVideo === video.id ? 'hidden' : ''}`}>
                  <div className="play-button">
                    <span className="play-icon">▶</span>
                  </div>
                </div>
                <div className="video-duration">{formatDuration(video.duration)}</div>
                <div className="video-category-badge">{video.category.toUpperCase()}</div>
              </div>
              <div className="video-info">
                <h3 className="video-title">{video.title}</h3>
                <div className="video-meta">
                  <span className="video-views">{video.views} views</span>
                  <span className="video-separator">•</span>
                  <span className="video-date">{video.uploadDate}</span>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Video Player Modal */}
        {selectedVideo && (
          <div className="video-modal-overlay" onClick={handleCloseVideo}>
            <div className="video-modal" onClick={(e) => e.stopPropagation()}>
              <button className="close-video-btn" onClick={handleCloseVideo}>
                <span>×</span>
              </button>
              <div className="video-player-container">
                <video
                  ref={videoRef}
                  src={selectedVideo.videoUrl}
                  controls
                  autoPlay
                  className="video-player"
                />
                <div className="video-player-info">
                  <h2 className="player-video-title">{selectedVideo.title}</h2>
                  <p className="player-video-description">{selectedVideo.description}</p>
                  <div className="player-video-meta">
                    <span>{selectedVideo.views} views</span>
                    <span>•</span>
                    <span>{selectedVideo.uploadDate}</span>
                    <span>•</span>
                    <span>{selectedVideo.duration}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
